{"security_risk":"LOW","command":"create","path":"/workspace/source/apps/customer-service/src/erasure-repository.ts","file_text":"import type { PoolClient } from 'pg';
import { v4 as uuid } from 'uuid';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import type { ErasureRequest } from '../../../packages/contracts/src/domain.js';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: 'pending' | 'processing' | 'failed' | 'completed';
  attempts: number;
  max_attempts: number;
  last_error: string | null;
  locked_by: string | null;
  locked_at: Date | null;
  lease_expires_at: Date | null;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
}

export interface ClaimedErasureRequest {
  id: string;
  merchant_id: string;
  customer_id: string;
  attempts: number;
  max_attempts: number;
}

export function toErasureRequestResponse(row: ErasureRequestRow): ErasureRequest {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureRequestRepository {
  async findForMerchant(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,max_attempts,last_error,
              locked_by,locked_at,lease_expires_at,created_at,updated_at,completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async findForCustomerInTransaction(client: PoolClient, merchantId: string, customerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,max_attempts,last_error,
              locked_by,locked_at,lease_expires_at,created_at,updated_at,completed_at
       FROM customers.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async createForCustomer(client: PoolClient, merchantId: string, customerId: string): Promise<ErasureRequestRow> {
    const id = uuid();
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(id,merchant_id,customer_id)
       VALUES($1,$2,$3)
       RETURNING id,merchant_id,customer_id,status,attempts,max_attempts,last_error,
                 locked_by,locked_at,lease_expires_at,created_at,updated_at,completed_at`,
      [id, merchantId, customerId],
    );
    return result.rows[0]!;
  }

  async recoverExpiredLeases(): Promise<number> {
    return await transaction(async (client) => {
      const result = await client.query(
        `UPDATE customers.erasure_requests
         SET status='pending',locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,
             last_error=COALESCE(last_error,'worker_lease_expired')
         WHERE status='processing' AND lease_expires_at IS NOT NULL AND lease_expires_at<now()`,
      );
      return result.rowCount ?? 0;
    });
  }

  async claim(workerId: string, leaseSeconds = 60): Promise<ClaimedErasureRequest | undefined> {
    return await transaction(async (client) => {
      const result = await client.query<ClaimedErasureRequest>(
        `UPDATE customers.erasure_requests r
         SET status='processing',attempts=r.attempts+1,locked_by=$1,locked_at=now(),
             lease_expires_at=now()+($2 || ' seconds')::interval,updated_at=now(),
             last_error=NULL
         FROM (
           SELECT id FROM customers.erasure_requests
           WHERE status='pending' AND attempts<max_attempts
           ORDER BY created_at FOR UPDATE SKIP LOCKED LIMIT 1
         ) picked
         WHERE r.id=picked.id
         RETURNING r.id,r.merchant_id,r.customer_id,r.attempts,r.max_attempts`,
        [workerId, leaseSeconds],
      );
      return result.rows[0];
    });
  }

  async markCompleted(merchantId: string, requestId: string): Promise<void> {
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status='completed',completed_at=now(),locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,
           last_error=NULL,updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
  }

  async markFailed(merchantId: string, requestId: string, attempts: number, maxAttempts: number,
                   error: { code: string; retryInSeconds: number }): Promise<void> {
    const exhausted = attempts >= maxAttempts;
    const availableSeconds = exhausted ? 0 : error.retryInSeconds;
    await pool.query(
      `UPDATE customers.erasure_requests
       SET status=$4,locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,last_error=$5,updated_at=now(),
           completed_at= CASE WHEN $4='completed' THEN now() ELSE completed_at END
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId, availableSeconds, exhausted ? 'failed' : 'pending', error.code],
    );
  }

  async recordEvent(merchantId: string, customerId: string, eventType: typeof EVENT_TYPES.CUSTOMER_ERASURE_REQUESTED
    | typeof EVENT_TYPES.CUSTOMER_ERASED, correlationId: string): Promise<void> {
    await transaction(async (client) => await addOutboxEvent(client, {
      eventType, aggregateType: 'customer', aggregateId: customerId, merchantId, correlationId,
      payload: { customerId },
    }));
  }
}"}

{"security_risk":"LOW","command":"create","path":"/workspace/source/apps/customer-service/src/erasure-cleanup.ts","file_text":"import { Client as MinioClient } from 'minio';
import { Redis } from 'ioredis';
import { searchClient, CUSTOMER_INDEX } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET } from '../../../packages/storage/src/minio.js';
import { config } from '../../../packages/config/src/index.js';

const SETTINGS = config();

/** Builds the deterministic Redis cache key for a merchant's customer view. */
function redisCustomerKey(merchantId: string, customerId: string): string {
  return `merchant:${merchantId}:customer:${customerId}`;
}

function redisActivityKey(merchantId: string, customerId: string): string {
  return `${redisCustomerKey(merchantId, customerId)}:activity`;
}

export interface CleanupOutcome {
  openSearchRemoved: boolean;
  redisRemoved: boolean;
  minioObjectsRemoved: number;
}

/**
 * Removes the customer's projection from the search index. Safe to call multiple times.
 * Errors are surfaced so the worker can retry rather than silently leaving PII behind.
 */
export async function removeCustomerFromSearch(merchantId: string, customerId: string): Promise<void> {
  await searchClient.delete({
    index: CUSTOMER_INDEX,
    id: `${merchantId}:${customerId}`,
  });
}

/** Removes the customer's cached projection and activity stream from Redis. */
export async function removeCustomerFromRedis(merchantId: string, customerId: string): Promise<void> {
  const redis = new Redis(SETTINGS.REDIS_URL);
  try {
    await redis.del(redisCustomerKey(merchantId, customerId), redisActivityKey(merchantId, customerId));
  } finally {
    await redis.quit();
  }
}

/**
 * Deletes an array of object keys from MinIO. Missing objects are treated as
 * success so retries converge on the same state.
 */
export async function deleteObjects(keys: ReadonlyArray<string>): Promise<number> {
  if (keys.length === 0) return 0;
  const client = new MinioClient({
    endPoint: SETTINGS.MINIO_ENDPOINT, port: SETTINGS.MINIO_PORT, useSSL: false,
    accessKey: SETTINGS.MINIO_ACCESS_KEY, secretKey: SETTINGS.MINIO_SECRET_KEY,
  });
  let removed = 0;
  for (const objectKey of keys) {
    try {
      await client.removeObject(DOCUMENT_BUCKET, objectKey);
      removed += 1;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      // MinIO returns NoSuchKey when the object is already gone; treat that as success.
      if (message.toLowerCase().includes('not found')) continue;
      throw error;
    }
  }
  return removed;
}"}

{"security_risk":"LOW","command":"create","path":"/workspace/source/apps/customer-service/src/erasure-service.ts","file_text":"import { v4 as uuid } from 'uuid';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { boundedExponentialBackoffSeconds } from '../../../packages/operations/src/retry-policy.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import {
  ErasureRequestRepository, type ClaimedErasureRequest, type ErasureRequestRow,
  toErasureRequestResponse,
} from './erasure-repository.js';
import { deleteObjects, removeCustomerFromRedis, removeCustomerFromSearch } from './erasure-cleanup.js';

const TOMBSTONE_ERASED_AT = '[erased]';
const STABLE_ERROR_CODES = {
  CUSTOMER_NOT_FOUND: 'customer_not_found',
  CLEANUP_FAILED: 'cleanup_failed',
  WORKER_LEASE_EXPIRED: 'worker_lease_expired',
} as const;

export interface ErasureRequestResult {
  status: number;
  body: ReturnType<typeof toErasureRequestResponse>;
}

/** Returns the canonical public shape for an erasure request row. */
export function respondErasureRequest(row: ErasureRequestRow): ReturnType<typeof toErasureRequestResponse> {
  return toErasureRequestResponse(row);
}

export class ErasureService {
  constructor(private readonly repository = new ErasureRequestRepository()) {}

  /**
   * Creates (or reuses) a data deletion request for the given customer. Idempotency keys are
   * scoped per merchant; reusing a key for a different customer surfaces a 409.
   */
  async create(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<ErasureRequestResult> {
    if (idempotencyKey.length < 8 || idempotencyKey.length > 200) {
      throw Object.assign(new Error('valid_idempotency_key_required'), { statusCode: 400 });
    }
    const requestHash = customerId;
    const correlationId = uuid();
    return await transaction(async (client) => {
      const replay = await this.reserveIdempotency(client, merchantId, idempotencyKey, requestHash);
      if (replay) return replay;

      const customerExists = await client.query(
        `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
        [merchantId, customerId],
      );
      if (!customerExists.rowCount) {
        throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });
      }

      const existing = await this.repository.findForCustomerInTransaction(client, merchantId, customerId);
      if (existing) {
        const body = respondErasureRequest(existing);
        await this.completeIdempotency(client, merchantId, idempotencyKey, 202, body);
        return { status: 202, body };
      }

      const request = await this.repository.createForCustomer(client, merchantId, customerId);
      await addOutboxEvent(client, {
        eventType: EVENT_TYPES.CUSTOMER_ERASURE_REQUESTED, aggregateType: 'customer',
        aggregateId: customerId, merchantId, correlationId, payload: { customerId, requestId: request.id },
      });
      await this.repository.recordEvent(merchantId, customerId, EVENT_TYPES.CUSTOMER_ERASURE_REQUESTED, correlationId);
      const body = respondErasureRequest(request);
      await this.completeIdempotency(client, merchantId, idempotencyKey, 202, body);
      return { status: 202, body };
    });
  }

  /** Looks up a request scoped to the authenticated merchant. */
  async findForMerchant(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    return this.repository.findForMerchant(merchantId, requestId);
  }

  /** Claims and processes one pending erasure request. Returns false when nothing was claimed. */
  async processOne(workerId: string): Promise<boolean> {
    await this.repository.recoverExpiredLeases();
    const claimed = await this.repository.claim(workerId);
    if (!claimed) return false;
    try {
      await this.runCleanup(claimed);
      await this.repository.markCompleted(claimed.merchant_id, claimed.id);
      await pool.query(
        `SELECT 1 FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
        [claimed.merchant_id, claimed.id],
      );
      await this.repository.recordEvent(claimed.merchant_id, claimed.customer_id, EVENT_TYPES.CUSTOMER_ERASED, uuid());
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      const code = this.classifyError(message);
      await this.repository.markFailed(
        claimed.merchant_id, claimed.id, claimed.attempts, claimed.max_attempts,
        { code, retryInSeconds: boundedExponentialBackoffSeconds(claimed.attempts) },
      );
    }
    return true;
  }

  /** Runs every cleanup step for a claimed request. Each step is idempotent. */
  private async runCleanup(request: ClaimedErasureRequest): Promise<void> {
    const { merchant_id: merchantId, customer_id: customerId } = request;

    // 1. Local scrubbing inside the database transaction.
    await transaction(async (client) => {
      await this.eraseCustomerRow(client, merchantId, customerId);
      await this.eraseOwnedChildren(client, merchantId, customerId);
      await this.eraseFinancialSnapshots(client, merchantId, customerId);
      await this.eraseSupportRecords(client, merchantId, customerId);
      await this.eraseOperationRecords(client, merchantId, customerId);
      await this.eraseProviderSandboxRecords(client, merchantId, customerId);
    });

    // 2. External services that cannot run inside a SQL transaction.
    await removeCustomerFromSearch(merchantId, customerId);
    await removeCustomerFromRedis(merchantId, customerId);
    const objectKeys = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM customers.customer_imports WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    ).then((result) => result.rows.map((row) => row.object_key));
    if (objectKeys.length > 0) await deleteObjects(objectKeys);

    // 3. Audit record. Kept on the platform layer where identities are scrubbed already.
    await pool.query(
      `INSERT INTO platform.audit_logs(merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
       VALUES($1,'system','customer',$2,'customer.erased',$3,$4)`,
      [merchantId, customerId, { requestId: request.id }, uuid()],
    );
  }

  /** Scrubs the customer row, keeping only the tombstone fields needed to anchor financial records. */
  private async eraseCustomerRow(client: import('pg').PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE customers.customers
       SET status='erased', email='erased:' || id::text,
           external_reference='erased:' || id::text,
           name=$3, phone=NULL, metadata='{}'::jsonb,
           updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId, TOMBSTONE_ERASED_AT],
    );
  }

  /** Deletes customer-owned child rows that do not carry financial meaning. */
  private async eraseOwnedChildren(client: import('pg').PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(`DELETE FROM customers.addresses WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.contacts WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.payment_method_refs WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
    await client.query(`DELETE FROM customers.customer_imports WHERE merchant_id=$1 AND customer_id=$2`, [merchantId, customerId]);
  }

  /** Strips PII from payment-side snapshots but keeps the customer_id reference and financial facts. */
  private async eraseFinancialSnapshots(client: import('pg').PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot = jsonb_build_object('id', customer_id, 'status', 'erased')
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.invoices SET billing_snapshot='{}'::jsonb WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.refunds SET customer_email=NULL WHERE merchant_id=$1
       AND payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.disputes
       SET evidence=jsonb_build_object('status', status)
       WHERE merchant_id=$1
         AND payment_intent_id IN (SELECT id FROM payments.payment_intents WHERE merchant_id=$1 AND customer_id=$2)`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.ledger_entries
       SET description = left(description, 0) || $3
       WHERE merchant_id=$1 AND reference_id=$2`,
      [merchantId, customerId, `[erased:${customerId}]`],
    );
  }

  /** Removes the customer's footprint from the support and ticket threads. */
  private async eraseSupportRecords(client: import('pg').PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM customers.support_messages
       WHERE merchant_id=$1 AND ticket_id IN (
         SELECT ticket_id FROM customers.support_participants WHERE customer_id=$2
       ) AND author_type='customer' AND author_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM customers.support_participants WHERE customer_id=$1`,
      [customerId],
    );
  }

  /** Scrubs the customer's PII from the operations schema. */
  private async eraseOperationRecords(client: import('pg').PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.analytics_events
       SET customer_id=NULL, email=NULL, properties='{}'::jsonb
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM operations.notification_preferences WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE operations.notifications
       SET customer_id=NULL, destination=$3, payload='{}'::jsonb
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, TOMBSTONE_ERASED_AT],
    );
    await client.query(
      `UPDATE operations.email_deliveries
       SET customer_id=NULL, destination=$3, subject=$3, text_body=$3, html_body=$3
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, TOMBSTONE_ERASED_AT],
    );
    await client.query(
      `UPDATE operations.document_manifests
       SET customer_id=NULL, metadata='{}'::jsonb
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
  }

  /** Removes the customer's footprint from the provider sandbox. */
  private async eraseProviderSandboxRecords(client: import('pg').PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `DELETE FROM provider_sandbox.customers WHERE merchant_id=$1 AND payflow_customer_id=$2`,
      [merchantId, customerId],
    );
  }

  private classifyError(message: string): string {
    if (message.includes('customer_not_found')) return STABLE_ERROR_CODES.CUSTOMER_NOT_FOUND;
    if (message.includes('lease_expired')) return STABLE_ERROR_CODES.WORKER_LEASE_EXPIRED;
    return STABLE_ERROR_CODES.CLEANUP_FAILED;
  }

  private async reserveIdempotency(
    client: import('pg').PoolClient,
    merchantId: string,
    key: string,
    hash: string,
  ): Promise<ErasureRequestResult | undefined> {
    const inserted = await client.query(
      `INSERT INTO operations.idempotency_keys(merchant_id,scope,key,request_hash,expires_at)
       VALUES($1,'customer-erasure-request',$2,$3,now()+interval '24 hours') ON CONFLICT DO NOTHING`,
      [merchantId, key, hash],
    );
    if (inserted.rowCount) return undefined;
    const existing = await client.query<{ request_hash: string; response_status: number | null; response_body: unknown }>(
      `SELECT request_hash,response_status,response_body FROM operations.idempotency_keys
       WHERE merchant_id=$1 AND scope='customer-erasure-request' AND key=$2 FOR UPDATE`, [merchantId, key],
    );
    const row = existing.rows[0];
    if (!row || row.request_hash !== hash) {
      throw Object.assign(new Error('idempotency_key_reused_for_different_customer'), { statusCode: 409 });
    }
    if (row.response_status === null) {
      throw Object.assign(new Error('idempotency_request_in_progress'), { statusCode: 409 });
    }
    return { status: row.response_status, body: row.response_body as ReturnType<typeof toErasureRequestResponse> };
  }

