    client: import('pg').PoolClient,
    merchantId: string,
    key: string,
    status: number,
    body: unknown,
  ): Promise<void> {
    await client.query(
      `UPDATE operations.idempotency_keys SET response_status=$4,response_body=$5
       WHERE merchant_id=$1 AND scope='customer-erasure-request' AND key=$3`,
      [merchantId, 'customer-erasure-request', key, status, body],
    );
  }
}"}

