import { pool } from '../../../packages/database/src/pool.js';
import { DOCUMENT_BUCKET } from '../../../packages/storage/src/minio.js';
import { config } from '../../../packages/config/src/index.js';

const SETTINGS = config();
const REDACTED_CUSTOMER = { status: 'erased' } as const;

/** Returns the receipt object keys the customer is associated with via payment intents. */
export async function listReceiptObjectKeys(merchantId: string, customerId: string): Promise<string[]> {
  const result = await pool.query<{ object_key: string }>(
    `SELECT d.object_key
     FROM operations.document_manifests d
     JOIN payments.payment_intents pi ON pi.merchant_id=d.merchant_id AND pi.id::text=d.metadata->>'paymentId'
     WHERE d.merchant_id=$1 AND d.document_type='receipt' AND pi.customer_id=$2`,
    [merchantId, customerId],
  );
  return result.rows.map((row) => row.object_key);
}

/**
 * Rewrites receipt objects so the customer section is a tombstone and the
 * financial facts are preserved. Missing objects are silently skipped.
 */
export async function redactReceipts(objectKeys: ReadonlyArray<string>): Promise<number> {
  if (objectKeys.length === 0) return 0;
  const client = new MinioClient({
    endPoint: SETTINGS.MINIO_ENDPOINT, port: SETTINGS.MINIO_PORT, useSSL: false,
    accessKey: SETTINGS.MINIO_ACCESS_KEY, secretKey: SETTINGS.MINIO_SECRET_KEY,
  });
  let redacted = 0;
  for (const objectKey of objectKeys) {
    try {
      const stream = await client.getObject(DOCUMENT_BUCKET, objectKey);
      const chunks: Buffer[] = [];
      for await (const chunk of stream as AsyncIterable<Buffer>) chunks.push(chunk);
      const existing = JSON.parse(Buffer.concat(chunks).toString('utf8')) as Record<string, unknown>;
      existing.customer = REDACTED_CUSTOMER;
      const body = JSON.stringify(existing);
      await client.putObject(DOCUMENT_BUCKET, objectKey, body, Buffer.byteLength(body), { 'Content-Type': 'application/json' });
      redacted += 1;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      if (message.toLowerCase().includes('not found')) continue;
      throw error;
    }
  }
  return redacted;
}"}

