{"security_risk":"LOW","command":"str_replace","path":"/workspace/source/apps/customer-service/src/erasure-service.ts","old_str":"/** Runs every cleanup step for a claimed request. Each step is idempotent. */
  private async runCleanup(request: ClaimedErasureRequest): Promise<void> {
