async function waitForCompletion(requestId: string, merchantId: string): Promise<{ status: string; attempts: number; lastError: string | null }> {
  for (let i = 0; i < 30; i++) {
    const result = await pool.query<{ status: string; attempts: number; last_error: string | null }>(
      `SELECT status,attempts,last_error FROM customers.erasure_requests WHERE id=$1 AND merchant_id=$2`,
      [requestId, merchantId],
    );
    const row = result.rows[0];
    if (!row) throw new Error('erasure request disappeared');
    if (row.status === 'completed' || row.status === 'failed') {
      return { status: row.status, attempts: row.attempts, lastError: row.last_error };
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error('timed out waiting for erasure worker');
}

