async function waitForCompletion(requestId: string, merchantId: string): Promise<{ status: string; attempts: number; lastError: string | null }> {
  for (let i = 0; i < 60; i++) {
    const result = await pool.query<{ status: string; attempts: number; last_error: string | null }>(
      `SELECT status,attempts,last_error FROM customers.erasure_requests WHERE id=$1 AND merchant_id=$2`,
      [requestId, merchantId],
    );
    const row = result.rows[0];
    if (!row) throw new Error('erasure request disappeared');
    if (row.status === 'completed' || row.status === 'failed') {
      return { status: row.status, attempts: row.attempts, lastError: row.last_error };
    }
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error('timed out waiting for erasure worker');
}

test('erasure end-to-end: customer row is scrubbed and PII is removed', async () => {
  const merchantId = randomUUID();
  const { customerId } = await buildCustomerWithFixtures({
    merchantId, externalReference: `erasure-e2e-${randomUUID()}`,
    email: 'e2e@example.test', name: 'E2E Tester',
  });
  const service = new ErasureService();
  const created = await service.create(merchantId, customerId, `erasure-suite-${randomUUID()}`);
  assert.equal(created.status, 202);
  assert.equal(created.body.customerId, customerId);
  const final = await waitForCompletion(created.body.id, merchantId);
  assert.equal(final.status, 'completed', `cleanup must succeed: ${final.lastError ?? ''}`);

  const row = (await pool.query<{ status: string; email: string; name: string; phone: string | null }>(
    `SELECT status,email,name,phone FROM customers.customers WHERE id=$1`, [customerId],
  )).rows[0];
  assert.equal(row.status, 'erased');
  assert.equal(row.email, `erased:${customerId}`);
  assert.equal(row.name, '[erased]');
  assert.equal(row.phone, null);

  for (const table of [
    'customers.addresses', 'customers.contacts', 'customers.payment_method_refs',
    'customers.support_participants', 'operations.notification_preferences',
  ]) {
    const count = (await pool.query<{ c: string }>(
      `SELECT COUNT(*)::text AS c FROM ${table} WHERE customer_id=$1`, [customerId],
    )).rows[0].c;
    assert.equal(count, '0', `${table} must have zero rows for erased customer`);
  }

  const analyticsWithPii = (await pool.query<{ c: string }>(
    `SELECT COUNT(*)::text AS c FROM operations.analytics_events
     WHERE merchant_id=$1 AND (customer_id=$2 OR email='e2e@example.test')`,
    [merchantId, customerId],
  )).rows[0].c;
  assert.equal(analyticsWithPii, '0', 'analytics events must not reference erased customer');

  const invoiceSnapshot = (await pool.query<{ snapshot: unknown }>(
    `SELECT billing_snapshot AS snapshot FROM payments.invoices WHERE customer_id=$1 LIMIT 1`, [customerId],
  )).rows[0]?.snapshot;
  assert.deepEqual(invoiceSnapshot, {}, 'invoice billing_snapshot must be cleared');

  const intentCount = (await pool.query<{ c: string }>(
    `SELECT COUNT(*)::text AS c FROM payments.payment_intents WHERE customer_id=$1`, [customerId],
  )).rows[0].c;
  assert.equal(intentCount, '1', 'payment intent must remain for financial audit');
});

test('erasure preserves financial records for compliance and audit', async () => {
  const merchantId = randomUUID();
  const { customerId } = await buildCustomerWithFixtures({
    merchantId, externalReference: `erasure-fin-${randomUUID()}`,
    email: 'fin@example.test', name: 'Fin Tester',
  });
  const refundsBefore = Number((await pool.query<{ c: string }>(
    `SELECT COUNT(*)::text AS c FROM payments.refunds WHERE merchant_id=$1 AND customer_email='fin@example.test'`, [merchantId],
  )).rows[0].c);
  assert.ok(refundsBefore > 0, 'refunds must exist before erasure');

  const service = new ErasureService();
  const created = await service.create(merchantId, customerId, `erasure-suite-${randomUUID()}`);
  const final = await waitForCompletion(created.body.id, merchantId);
  assert.equal(final.status, 'completed');

  const refundsAfter = Number((await pool.query<{ c: string }>(
    `SELECT COUNT(*)::text AS c FROM payments.refunds WHERE merchant_id=$1 AND customer_email='fin@example.test'`, [merchantId],
  )).rows[0].c);
  assert.equal(refundsAfter, 0, 'refund customer_email must be cleared');

  const refundsRecords = (await pool.query<{ c: string }>(
    `SELECT COUNT(*)::text AS c FROM payments.refunds WHERE merchant_id=$1`, [merchantId],
  )).rows[0].c;
